private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}

// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private var initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 26
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_app_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_add_game() != 7881 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_board_ids() != 59192 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_clear_focus() != 55769 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_connect() != 42838 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_focus_game() != 28079 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_pair() != 62791 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_pubkey() != 28199 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_remove_game() != 42137 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_rename() != 6726 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_request_catalog() != 54212 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_request_games() != 11447 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_app_core_checksum_method_scoreboardclient_reset_rotation() != 23733 {
